from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Find near-solid rectangles of non-background colors. Small internal
    # defects are noise; the selected rectangles are restored as solid blocks.
    candidates = []
    for color in set(x for row in grid for x in row if x != bg):
        for top in range(h):
            for bottom in range(top + 1, h):
                for left in range(w):
                    for right in range(left + 1, w):
                        area = (bottom - top + 1) * (right - left + 1)
                        count = sum(grid[r][c] == color
                                    for r in range(top, bottom + 1)
                                    for c in range(left, right + 1))
                        if count >= 4 and count / area >= 0.78:
                            candidates.append((area, count / area, top, bottom,
                                               left, right, color))

    # Prefer the largest, densest rectangles; do not allow rectangles to overlap.
    candidates.sort(reverse=True)
    chosen = []
    occupied = set()
    for area, density, top, bottom, left, right, color in candidates:
        cells = {(r, c) for r in range(top, bottom + 1)
                 for c in range(left, right + 1)}
        if not (cells & occupied):
            chosen.append((top, bottom, left, right, color))
            occupied.update(cells)

    out = [[bg] * w for _ in range(h)]
    for top, bottom, left, right, color in chosen:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                out[r][c] = color
    return out
